for (const [slug, body] of Object.entries(articles)) {
  const file = path.join(root, slug, 'index.html');
  let html = fs.readFileSync(file, 'utf8');
  const pattern = /(<div class="blog-content">)[\s\S]*?(<\/div>\s*<section class="author-box")/;
  if (!pattern.test(html)) throw new Error(`Article body not found: ${slug}`);
  html = html.replace(pattern, `$1${body}\n$2`);
  const toc = [...body.matchAll(/<(h2|h3)\s+id="([^"]+)"[^>]*>([\s\S]*?)<\/h[23]>/g)]
    .map(([_, tag, id, label]) => `<li class="toc-depth-${tag === 'h2' ? '2' : '3'}"><a href="#${id}">${label.replace(/<[^>]*>/g, '').trim()}</a></li>`)
    .join('');
  const tocPattern = /(<nav class="toc-nav">\s*<ul[^>]*>)[\s\S]*?(<\/ul>\s*<\/nav>)/;
  if (!tocPattern.test(html)) throw new Error(`Table of contents not found: ${slug}`);
  html = html.replace(tocPattern, `$1${toc}$2`);
  if (slug === 'tornillos-metricos-m3-m16') {
    const outdated = 'Consulta diámetros nominales, pasos de rosca habituales y tamaños de llave para tornillos métricos M3 a M16.';
    const revised = 'Consulta los diámetros nominales y pasos gruesos habituales de tornillos métricos M3 a M16. Verifica cada medida en la norma y ficha técnica.';
    html = html.replaceAll(outdated, revised);
  }
  html = html.replace(/(<img class="blog-hero-image"[^>]*alt=")[^"]*(")/, `$1${heroAlts[slug]}$2`);
  html = html.replaceAll('Sendero de retorno', 'Ruta de navegación');
  html = html.replaceAll('Camino de regreso', 'Ruta de navegación');
  html = html.replaceAll('class="table-responsive"', 'class="reference-table-wrapper"');
  fs.writeFileSync(file, html);
}
console.log(`Rewrote ${Object.keys(articles).length} added-guide bodies, synced their TOCs, refreshed hero alt text, and corrected one mismatched meta description.`);
